function a(t){return String(t??"").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}function f(t){if(!t)return"—";const e=new Date(t);return Number.isNaN(e.getTime())?"—":new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric"}).format(e)}function u(t){return String(t??"").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"")}function s(t){if(!t)return"há pouco";const e=new Date(t);if(Number.isNaN(e.getTime()))return"há pouco";const i=Date.now()-e.getTime(),r=Math.max(1,Math.floor(i/6e4));if(r<60)return`há ${r} min`;const n=Math.floor(r/60);return n<24?`há ${n} h`:`há ${Math.floor(n/24)} d`}export{f,u as n,a as s,s as t};
